public final class JoggerActivity extends Activity {
 private Core.Store store;private LinearLayout page;private TextView status;private boolean busy;private String current,importId;private boolean importPacks;private ProgressDialog progress;
 interface Task {void run()throws Exception;}
 private int dp(int p){return Math.round(p*getResources().getDisplayMetrics().density);}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xfffafafa);getWindow().setNavigationBarColor(0xfffafafa);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);store=new Core.Store(this);try{if(store.all().isEmpty())store.create("My first world","1.21.4","Vanilla");current=store.prefs.getString("selected",store.all().get(0).getString("id"));home();if(BuildConfig.DEBUG&&getIntent().getBooleanExtra("probe",false)){startActivity(new Intent(this,GameActivity.class).putExtra("probe",true));return;}if(getIntent().hasExtra("instance")){current=getIntent().getStringExtra("instance");store.instance(current);home();if(getIntent().getBooleanExtra("quick",false))play(false);}}catch(Exception e){showError(e);}}
 private void frame(String title){ScrollView sc=new ScrollView(this);sc.setFillViewport(true);page=new LinearLayout(this);page.setOrientation(1);page.setPadding(dp(24),dp(16),dp(24),dp(28));page.setBackgroundColor(0xfffafafa);sc.addView(page);setContentView(sc);text(title,28,true);space(8);}
 private void space(int n){Space s=new Space(this);page.addView(s,new LinearLayout.LayoutParams(1,dp(n)));}
 private TextView text(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xff191919);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setPadding(0,dp(4),0,dp(8));page.addView(t,new LinearLayout.LayoutParams(-1,-2));return t;}
 private Button button(String label,boolean main,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(16);b.setTextColor(main?Color.WHITE:0xff191919);GradientDrawable bg=new GradientDrawable();bg.setColor(main?0xff202020:Color.WHITE);bg.setCornerRadius(dp(7));bg.setStroke(dp(1),0xffd3d3d3);b.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(50));lp.setMargins(0,dp(5),0,dp(5));page.addView(b,lp);b.setOnClickListener(v->{if(busy){Toast.makeText(this,"A task is running. Cancel it before changing instances.",Toast.LENGTH_SHORT).show();return;}action.run();});return b;}
 private void home(){frame("Minecraft Jogger");text("Your worlds. Your mods. On your phone.",16,false);String name="Not signed in";try{JSONObject a=new Account(this).load();if(a!=null)name="Signed in as "+a.getString("name");}catch(Exception ignored){}text(name,14,false);button("Microsoft sign-in with a code",false,this::login);space(14);
  try{JSONObject j=store.instance(current);text(j.getString("name"),23,true);text(j.getString("version")+"  |  "+j.getString("loader")+"  |  "+j.optString("preset","Custom"),15,false);button("Play Java Edition",true,()->play(false));button("Play the official Minecraft demo",false,()->play(true));}catch(Exception e){text("Choose an instance below",16,false);}
  space(12);button("Instances",false,this::instances);button("Mods and resource packs",false,this::library);button("Settings and controls",false,this::settings);status=text("Independent build 0.3.0 - original launcher and native window/input code",13,false);text("Not an official Minecraft product. Not associated with Mojang or Microsoft.",12,false);
 }
 private void instances(){frame("Instances");button("Create an instance",true,this::create);for(JSONObject j:store.all()){String id=j.optString("id");button(j.optString("name")+"   /   "+j.optString("version")+" "+j.optString("loader"),false,()->{current=id;store.prefs.edit().putString("selected",id).apply();instancePage();});}button("Back",false,this::home);}
 private void create(){LinearLayout l=form();EditText n=field(l,"Instance name","New world"),v=field(l,"Minecraft version","1.21.4");Spinner loader=spinner(l,new String[]{"Vanilla","Fabric","Quilt"});new AlertDialog.Builder(this).setTitle("Create instance").setView(l).setPositiveButton("Create",(d,w)->{try{String name=n.getText().toString().trim(),version=v.getText().toString().trim();if(name.isEmpty()||name.length()>80||!version.matches("[a-zA-Z0-9._-]{1,50}"))throw new IOException("Enter a name and valid version ID");JSONObject j=store.create(name,version,loader.getSelectedItem().toString());current=j.getString("id");store.prefs.edit().putString("selected",current).apply();instancePage();}catch(Exception e){showError(e);}}).setNegativeButton("Cancel",null).show();}
 private void instancePage(){try{JSONObject j=store.instance(current);frame(j.getString("name"));text(j.getString("version")+" / "+j.getString("loader"),16,false);text("Worlds, mods, packs and options are isolated in this instance.",14,false);button("Play",true,()->play(false));button("Add to home screen",false,()->pin(j));button("Performance preset",false,()->presets(j));button("Memory and render resolution",false,()->instanceSettings(j));button("Rename",false,()->{LinearLayout l=form();EditText n=field(l,"Name",j.optString("name"));new AlertDialog.Builder(this).setTitle("Rename instance").setView(l).setPositiveButton("Save",(d,w)->{try{j.put("name",n.getText().toString());store.save(j);instancePage();}catch(Exception e){showError(e);}}).setNegativeButton("Cancel",null).show();});button("Mods and resource packs",false,this::library);button("View game log",false,this::log);button("Back to instances",false,this::instances);}catch(Exception e){showError(e);}}
 private void pin(JSONObject j){try{ShortcutManager sm=getSystemService(ShortcutManager.class);if(!sm.isRequestPinShortcutSupported())throw new IOException("This home-screen app does not support pinned shortcuts");Intent i=new Intent(this,JoggerActivity.class).setAction(Intent.ACTION_VIEW).putExtra("instance",j.getString("id")).putExtra("quick",true);ShortcutInfo shortcut=new ShortcutInfo.Builder(this,"jogger-"+j.getString("id")).setShortLabel(j.getString("name")).setLongLabel("Play "+j.getString("name")).setIcon(Icon.createWithResource(this,R.drawable.jogger_icon)).setIntent(i).build();sm.requestPinShortcut(shortcut,null);}catch(Exception e){showError(e);}}
 private void presets(JSONObject j){new AlertDialog.Builder(this).setTitle("Mobile performance").setItems(new String[]{"Balanced: 6 chunks, 60 FPS, 70% resolution","Battery: 4 chunks, 30 FPS, 55% resolution","Quality: 10 chunks, 60 FPS, 100% resolution","Restore original game options"},(d,which)->runTask("Applying settings",()->{File dir=store.dir(j.getString("id"));if(which==3){store.restore(dir);j.put("preset","Custom");}else{String p=new String[]{"Balanced","Battery","Quality"}[which];store.preset(dir,p);j.put("preset",p).put("resolution",new int[]{70,55,100}[which]);}store.save(j);},this::instancePage)).show();}
 private void instanceSettings(JSONObject j){LinearLayout l=form();EditText ram=field(l,"Java memory (MiB)",String.valueOf(j.optInt("ram",2048))),res=field(l,"Render resolution (%)",String.valueOf(j.optInt("resolution",70)));ram.setInputType(2);res.setInputType(2);new AlertDialog.Builder(this).setTitle("Instance settings").setView(l).setMessage("Keep enough memory free for Android. Changes apply next launch.").setPositiveButton("Save",(d,w)->{try{int m=Integer.parseInt(ram.getText().toString()),r=Integer.parseInt(res.getText().toString());if(m<768||m>6144||r<40||r>100)throw new IOException("Memory range: 768-6144 MiB; resolution: 40-100%");j.put("ram",m).put("resolution",r);store.save(j);instancePage();}catch(Exception e){showError(e);}}).setNegativeButton("Cancel",null).show();}
 private void play(boolean demo){final String id=current;runTask("Preparing Minecraft",()->{JSONObject j=store.instance(id);JSONObject account=demo?null:new Account(this).current();new Core.Installer(store,this::progress).prepare(j,account,demo);},()->startActivity(new Intent(this,GameActivity.class)));}
 private void settings(){frame("Settings and controls");text("Classic mobile layout",21,true);text("Left directional buttons with centre crouch. Double-tap Forward to sprint. Jump and action buttons are on the right. The ... button beside the nine hotbar slots opens inventory. Tap the world to use/place, hold to mine, drag to look.",15,false);button("Try the controls",true,()->startActivity(new Intent(this,GameActivity.class).putExtra("controlsTest",true)));button("Check Java + graphics engine",false,()->startActivity(new Intent(this,GameActivity.class).putExtra("probe",true)));button("Look sensitivity",false,()->{LinearLayout l=form();EditText v=field(l,"Sensitivity percent",String.valueOf(store.prefs.getInt("lookSpeed",100)));v.setInputType(2);new AlertDialog.Builder(this).setTitle("Look sensitivity").setView(l).setPositiveButton("Save",(d,w)->{try{int n=Integer.parseInt(v.getText().toString());if(n<15||n>300)throw new IOException("Use 15-300%");store.prefs.edit().putInt("lookSpeed",n).apply();}catch(Exception e){showError(e);}}).setNegativeButton("Cancel",null).show();});button("Microsoft application ID",false,this::clientId);button("Sign out",false,()->{new Account(this).remove();home();});button("Credits and source",false,()->{try{String txt=Core.assetText(this,"CREDITS.txt");new AlertDialog.Builder(this).setTitle("Independent Jogger").setMessage(txt).setPositiveButton("Close",null).setNeutralButton("Source",(d,w)->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/itswiktoragain/gpt-on-the-move/tree/jogger-independent/jogger-independent")))).show();}catch(Exception e){showError(e);}});button("Back",false,this::home);}
 private void clientId(){LinearLayout l=form();EditText id=field(l,"Your Microsoft public-client application ID",store.prefs.getString("clientId",BuildConfig.MICROSOFT_CLIENT_ID));new AlertDialog.Builder(this).setTitle("Microsoft OAuth configuration").setMessage("Use an application you own, with personal Microsoft accounts and public-client device-code flow enabled. Minecraft/Xbox access must be allowed for that application. No client secret is needed. Jogger does not reuse another launcher's identity.").setView(l).setPositiveButton("Save",(d,w)->store.prefs.edit().putString("clientId",id.getText().toString().trim()).apply()).setNegativeButton("Cancel",null).show();}
 private void login(){String id=store.prefs.getString("clientId",BuildConfig.MICROSOFT_CLIENT_ID);if(id.isEmpty()){clientId();return;}busy=true;Core.cancel.set(false);AtomicBoolean stop=new AtomicBoolean();ProgressDialog request=new ProgressDialog(this);request.setMessage("Requesting Microsoft sign-in code...");request.setCancelable(true);request.setOnCancelListener(d->stop.set(true));request.show();Core.WORK.execute(()->{try{new Account(this).login(id,stop,(code,url,seconds)->runOnUiThread(()->{request.dismiss();TextView t=new TextView(this);t.setPadding(dp(24),dp(20),dp(24),dp(16));t.setTextSize(22);t.setTextIsSelectable(true);t.setText(code+"\n\nEnter this code on Microsoft's page, then sign in with your email.\nExpires in "+seconds/60+" minutes.");AlertDialog dlg=new AlertDialog.Builder(this).setTitle("Microsoft sign-in").setView(t).setPositiveButton("Open Microsoft",null).setNeutralButton("Copy code",null).setNegativeButton("Cancel",(d,w)->stop.set(true)).create();dlg.setOnCancelListener(d->stop.set(true));dlg.setOnShowListener(d->{dlg.getButton(-1).setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url))));dlg.getButton(-3).setOnClickListener(v->((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Microsoft sign-in code",code)));});dlg.show();codeDialog=dlg;}));runOnUiThread(()->{busy=false;request.dismiss();if(codeDialog!=null)codeDialog.dismiss();home();});}catch(Exception e){runOnUiThread(()->{busy=false;request.dismiss();if(codeDialog!=null)codeDialog.dismiss();showError(e);});}});}
 private AlertDialog codeDialog;
 private void library(){try{JSONObject j=store.instance(current);frame("Mods and resource packs");text(j.getString("name")+" / "+j.getString("version")+" "+j.getString("loader"),16,false);button("Find mods on Modrinth",true,()->browse(false));button("Find resource packs",false,()->browse(true));button("Import a mod JAR",false,()->importFile(false));button("Import a resource pack ZIP",false,()->importFile(true));button("Download from HTTPS URL",false,this::urlDownload);button("Installed files",false,this::installed);text("Only install JARs you trust: mods execute code inside the game. Resource packs are enabled in Minecraft's own Resource Packs menu.",13,false);button("Back",false,this::home);}catch(Exception e){showError(e);}}
 private void browse(boolean packs){LinearLayout l=form();EditText query=field(l,"Search","");new AlertDialog.Builder(this).setTitle(packs?"Find resource packs":"Find mods").setView(l).setPositiveButton("Search",(d,w)->{final String id=current;final JSONArray[]result={null};runTask("Searching Modrinth",()->{JSONObject j=store.instance(id);result[0]=Content.search(query.getText().toString(),j.getString("version"),j.getString("loader"),packs);},()->{JSONArray a=result[0];String[]names=new String[a.length()];for(int i=0;i<names.length;i++)names[i]=a.optJSONObject(i).optString("title");if(names.length==0){showError(new IOException("No matching projects"));return;}new AlertDialog.Builder(this).setTitle("Select a project").setItems(names,(dd,index)->{JSONObject hit=a.optJSONObject(index);new AlertDialog.Builder(this).setTitle(hit.optString("title")).setMessage(hit.optString("description")+"\n\nDownload compatible files and required dependencies?").setPositiveButton("Install",(ddd,www)->runTask("Installing content",()->{JSONObject j=store.instance(id);Content.install(hit.getString("project_id"),j,store.dir(id),packs,this::progress);},this::installed)).setNegativeButton("Cancel",null).show();}).setNegativeButton("Close",null).show();});}).setNegativeButton("Cancel",null).show();}
 private void importFile(boolean packs){importId=current;importPacks=packs;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");startActivityForResult(i,30);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=30||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();final String id=importId;final boolean packs=importPacks;runTask("Importing file",()->{String name=null;try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}if(name==null)throw new IOException("Cannot read filename");name=Content.safeName(name,packs);File dir=store.dir(id),target=Core.inside(new File(dir,packs?"resourcepacks":"mods"),name),temp=new File(dir,"import.part");if(target.exists())throw new IOException("A file with that name is already installed");try{try(InputStream in=getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(temp)){if(in==null)throw new IOException("Cannot open selected file");Core.copy(in,out,512L*1024*1024);}Core.archive(temp,packs);Files.move(temp.toPath(),target.toPath(),StandardCopyOption.ATOMIC_MOVE);}finally{temp.delete();}},this::installed);}
 private void urlDownload(){LinearLayout l=form();EditText url=field(l,"HTTPS URL","https://"),name=field(l,"Filename (including .jar or .zip)","");Spinner kind=spinner(l,new String[]{"Mod JAR","Resource-pack ZIP"});final String id=current;new AlertDialog.Builder(this).setTitle("Download content").setView(l).setMessage("A direct download URL is required. HTTPS protects transport; it does not establish that a JAR is safe.").setPositiveButton("Download",(d,w)->runTask("Downloading",()->Content.fromUrl(url.getText().toString().trim(),name.getText().toString().trim(),store.dir(id),kind.getSelectedItemPosition()==1),this::installed)).setNegativeButton("Cancel",null).show();}
 private void installed(){try{frame("Installed files");File dir=store.dir(current);for(String folder:new String[]{"mods","resourcepacks"}){text(folder.equals("mods")?"Mods":"Resource packs",20,true);File[]files=new File(dir,folder).listFiles();if(files==null||files.length==0)text("No files installed yet",14,false);else for(File f:files){if(!f.isFile())continue;button(f.getName(),false,()->new AlertDialog.Builder(this).setTitle(f.getName()).setItems(new String[]{f.getName().endsWith(".disabled")?"Enable":"Disable","Delete"},(d,which)->{try{if(which==1){new AlertDialog.Builder(this).setTitle("Delete this file?").setMessage(f.getName()).setPositiveButton("Delete",(dd,ww)->{if(!f.delete())showError(new IOException("Could not delete file"));installed();}).setNegativeButton("Cancel",null).show();}else{String n=f.getName().endsWith(".disabled")?f.getName().substring(0,f.getName().length()-9):f.getName()+".disabled";File dest=new File(f.getParentFile(),n);if(dest.exists())throw new IOException("Destination already exists");Files.move(f.toPath(),dest.toPath());installed();}}catch(Exception e){showError(e);}}).setNegativeButton("Close",null).show());}}button("Back",false,this::library);}catch(Exception e){showError(e);}}
 private void log(){try{File f=new File(store.dir(current),"latest-jogger.log");if(!f.exists())throw new IOException("This instance has no engine log yet");String s=Core.text(f);frame("Game log");TextView t=text(s.substring(Math.max(0,s.length()-30000)),12,false);t.setTextIsSelectable(true);button("Share log",false,()->{Intent i=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,t.getText().toString());startActivity(Intent.createChooser(i,"Share Jogger log"));});button("Back",false,this::instancePage);}catch(Exception e){showError(e);}}
 private LinearLayout form(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(20),dp(8),dp(20),dp(12));return l;}
 private EditText field(LinearLayout l,String hint,String value){TextView t=new TextView(this);t.setText(hint);l.addView(t);EditText e=new EditText(this);e.setSingleLine();e.setText(value);l.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
 private Spinner spinner(LinearLayout l,String[]values){Spinner s=new Spinner(this);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values);s.setAdapter(a);l.addView(s);return s;}
 private void progress(String s){runOnUiThread(()->{if(progress!=null&&progress.isShowing())progress.setMessage(s);});}
 private void runTask(String title,Task work,Runnable success){if(busy)return;busy=true;Core.cancel.set(false);progress=new ProgressDialog(this);progress.setTitle(title);progress.setMessage("Starting...");progress.setCancelable(false);progress.setButton(DialogInterface.BUTTON_NEGATIVE,"Cancel",(d,w)->Core.cancel.set(true));progress.show();Core.WORK.execute(()->{try{work.run();runOnUiThread(()->{busy=false;progress.dismiss();success.run();});}catch(Throwable e){runOnUiThread(()->{busy=false;progress.dismiss();showError(e);});}});}
 private void showError(Throwable e){String msg=e.getMessage();if(msg==null)msg=e.toString();new AlertDialog.Builder(this).setTitle("Minecraft Jogger").setMessage(msg).setPositiveButton("OK",null).show();}
 @Override protected void onDestroy(){if(isFinishing())Core.cancel.set(true);super.onDestroy();}
}
